//! wifi-connect：SAE 多群的主机用例（`sae_groups.zig`、`bignum.zig`、`ecc.zig` 的通用后端，
//! 以及 `sae_full.zig` 的 `Groups()`）。
//!
//! `cd components/wifi-connect/src && env -u LD_LIBRARY_PATH zig test sae_groups_tests.zig`
//! 可以单独作测试根；`host_tests.zig` 末尾也 import 了它。
//!
//! 向量来源（都不是官方向量；group 19 的官方向量 Annex J.10 在 `sae_full_tests.zig` 里对）：
//!   * `/tmp/s31-oracle/sae_groups_oracle.py`：纯 Python 大整数 + hashlib/hmac 的参照实现，
//!     域参数取自 hostap dh_groups.c / mbedTLS ecp_curves.c，并与 RFC 2409 / 3526、cryptography
//!     交叉核对（`selftest` 160 PASS / 0 FAIL）。文件末尾的常量块由 `sae_groups_gen.py` 从它生成：
//!     每群若干条固定种子的整链向量、pwd-value、FFC 的小指数模指数。
//!   * `cryptography` 的公钥 d·G：各 ECC 群标量乘的期望值（不是 oracle 的仿射运算算的）。
//!
//! Debug 下 FFC 的大群一次模指数很慢（x86_64 实测：2048 位约 3 s，3072 位约 6 s，4096 位更长；
//! 一条整链要 8 次），所以仓库里的整链向量：
//!   * 2 / 5 / 14 各留 6 / 4 / 2 条；
//!   * 15 / 16 / 17 / 18 只对 pwd-value、PWE 与小指数模指数。每群 ≥ 100 组随机输入的整链对拍在
//!     ReleaseFast 下跑一次性差分（`/tmp/s31-oracle/saediff/diff.zig` 对 oracle 的 `vectors`），
//!     结果写在交付报告里。
//!
//! 条款出处分两类，与 `sae_groups.zig`、`sae_full.zig` 文件头一致：(a) 有 2016 条款依据的写
//! 条款号；(b) 802.11-2016 无此条款、只依据 hostap 源码的（Password Identifier、Rejected Groups
//! 元素、P-521 的 pwd-value 取法）在用例名里注明 hostap。

const std = @import("std");

const testing = std.testing;
const expect = testing.expect;
const expectEqual = testing.expectEqual;
const expectEqualSlices = testing.expectEqualSlices;
const expectError = testing.expectError;

const bignum = @import("bignum.zig");
const sae = @import("sae.zig");
const sf = @import("sae_full.zig");
const sg = @import("sae_groups.zig");

const selftest_host = @import("selftest_host.zig");
const sae_groups_selftest = @import("sae_groups_selftest.zig");

// ---------------------------------------------------------------------------
// 向量的形状（常量块在文件末尾）
// ---------------------------------------------------------------------------

/// 编译期解码十六进制字面量。向量动辄上千字节，超过默认的 1000 步分支额度。分支计数在一个声明
/// 的求值里是**累计**的（同一个数组字面量里的所有字面量都算在内），额度却只能抬高，按单个字面量
/// 的长度给的额度会不够（实测 `kat_2` 就越过了 26600 步）：这里给整块一个够大的额度。
fn hx(comptime s: []const u8) [s.len / 2]u8 {
    @setEvalBranchQuota(2_000_000);
    return @import("vectors.zig").hex(s);
}

/// 编译期整数 → `m` 个八位组的大端串。
fn be(comptime v: comptime_int, comptime m: usize) [m]u8 {
    var out: [m]u8 = undefined;
    inline for (0..m) |i| out[i] = @truncate(v >> @intCast(8 * (m - 1 - i)));
    return out;
}

/// 一条整链向量：输入是两个 MAC、口令、两端的 rand / mask，其余是期望值。
/// 17、18 两条大群只填到 `pwe`。
pub const Kat = struct {
    mac_a: []const u8,
    mac_b: []const u8,
    password: []const u8,
    rand_a: []const u8 = &.{},
    mask_a: []const u8 = &.{},
    rand_b: []const u8 = &.{},
    mask_b: []const u8 = &.{},
    counter: u8,
    pwd_value: []const u8,
    pwe: []const u8,
    scalar_a: []const u8 = &.{},
    element_a: []const u8 = &.{},
    scalar_b: []const u8 = &.{},
    element_b: []const u8 = &.{},
    k: []const u8 = &.{},
    keyseed: []const u8 = &.{},
    kck: []const u8 = &.{},
    pmk: []const u8 = &.{},
    pmkid: []const u8 = &.{},
    confirm_a: []const u8 = &.{},
    confirm_b: []const u8 = &.{},
};

/// FFC 的 base^exp mod p：`exp` 是编译期整数，测试时转成 m 个八位组。
pub const PowVec = struct { base: []const u8, exp: comptime_int, want: []const u8 };

/// FFC 的模逆 a^(p−2)。
pub const InvVec = struct { base: []const u8, want: []const u8 };

/// cryptography 算出的 d·G。
pub const DG = struct { d: []const u8, x: []const u8, y: []const u8 };

