const mac_a: [6]u8 = .{ 0x7b, 0x88, 0x56, 0x20, 0x2d, 0x8d };
const mac_b: [6]u8 = .{ 0xe2, 0x47, 0x1c, 0x0a, 0x5a, 0xcb };
const mac_c: [6]u8 = .{ 0x02, 0xcc, 0x00, 0x00, 0x00, 0x01 };
const pw = "sae-groups-pw";

fn eq(a: []const u8, b: []const u8) bool {
    return std.mem.eql(u8, a, b);
}

fn macOf(s: []const u8) [6]u8 {
    return s[0..6].*;
}

var g_seed: u64 = 1;

/// 确定性随机源（splitmix64）。
fn rngFill(out: []u8) void {
    for (out) |*c| {
        g_seed +%= 0x9E37_79B9_7F4A_7C15;
        var z = g_seed;
        z = (z ^ (z >> 30)) *% 0xBF58_476D_1CE4_E5B9;
        z = (z ^ (z >> 27)) *% 0x94D0_49BB_1331_11EB;
        c.* = @truncate(z ^ (z >> 31));
    }
}

