test "sae groups: params() lengths equal the oracle's table for all 15 groups (12.4.7.2.2, 12.4.7.2.4)" {
    // /tmp/s31-oracle/sae_groups_oracle.py params 的输出：group、kind、m（素数与标量的八位组数）、
    // element_len
    const want = [_]struct { id: sg.Id, kind: sg.Kind, m: u16, e: u16 }{
        .{ .id = .ffc_2, .kind = .ffc, .m = 128, .e = 128 },
        .{ .id = .ffc_5, .kind = .ffc, .m = 192, .e = 192 },
        .{ .id = .ffc_14, .kind = .ffc, .m = 256, .e = 256 },
        .{ .id = .ffc_15, .kind = .ffc, .m = 384, .e = 384 },
        .{ .id = .ffc_16, .kind = .ffc, .m = 512, .e = 512 },
        .{ .id = .ffc_17, .kind = .ffc, .m = 768, .e = 768 },
        .{ .id = .ffc_18, .kind = .ffc, .m = 1024, .e = 1024 },
        .{ .id = .ecc_19, .kind = .ecc, .m = 32, .e = 64 },
        .{ .id = .ecc_20, .kind = .ecc, .m = 48, .e = 96 },
        .{ .id = .ecc_21, .kind = .ecc, .m = 66, .e = 132 },
        .{ .id = .ecc_25, .kind = .ecc, .m = 24, .e = 48 },
        .{ .id = .ecc_26, .kind = .ecc, .m = 28, .e = 56 },
        .{ .id = .ecc_28, .kind = .ecc, .m = 32, .e = 64 },
        .{ .id = .ecc_29, .kind = .ecc, .m = 48, .e = 96 },
        .{ .id = .ecc_30, .kind = .ecc, .m = 64, .e = 128 },
    };
    inline for (want) |w| {
        const p = sg.params(w.id);
        try expectEqual(w.id, p.id);
        try expectEqual(w.kind, p.kind);
        try expectEqual(w.m, p.prime_len);
        try expectEqual(w.e, p.element_len);
        // 表里的长度与群的类型一致：标量与 p 的八位组数相同（12.4.7.4 对 r 的 m）
        const G = sg.Group(w.id);
        try expectEqual(@as(usize, w.m), G.m);
        try expectEqual(@as(usize, w.e), G.element_len);
        try expectEqual(@as(usize, w.m), G.order.len);
        try expectEqual(@as(usize, w.m), G.prime.len);
    }
    try expectEqual(@as(usize, 15), sg.all.len);
}

