    // 31–34、35–37：见 sae_groups.zig 文件头「没做的」
    for ([_]u16{ 0, 1, 3, 4, 6, 22, 23, 24, 27, 31, 32, 33, 34, 35, 36, 37, 0xffff }) |v| {
