test "sae groups: domain parameters agree with the existing P-256 constants and with the oracle's orders" {
    const G19 = sg.Group(.ecc_19);
    // P-256：与 sae.zig 里原有的 p、n（Annex J.10 的输入）相等
    try expectEqualSlices(u8, &sae.prime, G19.prime);
    try expectEqualSlices(u8, &sae.order, G19.order);
    // 实现从标准库取 n；期望值是 oracle 从 mbedTLS 读出、并与 cryptography 的 group_order
    // 交叉核对后印出来的
    try expectEqualSlices(u8, &sg.ecc_19_n, G19.order);
    try expectEqualSlices(u8, &sg.ecc_20_n, sg.Group(.ecc_20).order);
    try expectEqual(@as(u16, 256), G19.prime_bits);
    try expectEqual(@as(u16, 384), sg.Group(.ecc_20).prime_bits);
    try expectEqual(@as(u16, 521), sg.Group(.ecc_21).prime_bits);
    // 15 个群的基点都在曲线上、阶都是 r：n·G 是无穷远点
    inline for (.{ sg.Id.ecc_19, sg.Id.ecc_20, sg.Id.ecc_21, sg.Id.ecc_25, sg.Id.ecc_26, sg.Id.ecc_28, sg.Id.ecc_29, sg.Id.ecc_30 }) |id| {
        const C = sg.CurveOf(id, bignum.native_limb_bits);
        const G = sg.Group(id);
        try expect(C.isOnCurve(C.PointT.base.x, C.PointT.base.y));
        try expect(C.mul(G.order.*, C.PointT.base).isInfinity());
        const neg = C.PointT.base.neg();
        try expect(C.add(C.PointT.base, neg).isInfinity());
    }
}

test "sae groups: the std P-384 prime equals mbedTLS secp384r1_p; std P-256 equals sae.prime" {
    // mbedTLS ecp_curves.c:306–313 的 secp384r1_p，由 oracle 读出（它的 selftest 核对了
    // G 在曲线上、n 等于 cryptography 的 group_order）。标准库的 P384 自己带 p，这里只对 p。
    const p384: [48]u8 = hx("fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffeffffffff0000000000000000ffffffff");
    try expectEqualSlices(u8, &p384, sg.Group(.ecc_20).prime);
    const G19 = sg.Group(.ecc_19);
    try expectEqualSlices(u8, &sae.prime, G19.prime);
}
