fn dGAll(comptime id: sg.Id, pts: []const DG) !void {
    const C = sg.CurveOf(id, bignum.native_limb_bits);
    const m = C.coord_len;
    for (pts) |p| {
        const got = C.mul(p.d[0..m].*, C.PointT.base);
        const bytes = got.toBytes();
        try expectEqualSlices(u8, p.x, bytes[0..m]);
        try expectEqualSlices(u8, p.y, bytes[m..]);
    }
}

