fn curveLaws(comptime id: sg.Id) !void {
    const C = sg.CurveOf(id, bignum.native_limb_bits);
    const m = C.coord_len;
    const g = C.PointT.base;
    const a = C.mul(be(7, m), g);
    const b = C.mul(be(11, m), g);
    const ab = C.mul(be(18, m), g);
    try expect(!a.eql(b));
    // 交换律、结合律
    try expect(C.add(a, b).eql(ab) and C.add(b, a).eql(ab));
    try expect(C.add(C.add(a, b), a).eql(C.add(a, C.add(b, a))));
    // 单位元与逆元（12.4.4.2.1）
    const o = C.add(a, a.neg());
    try expect(o.isInfinity() and C.add(o, b).eql(b) and C.add(b, o).eql(b));
    try expect(C.add(a, C.PointT.infinity).eql(a));
    try expect(C.add(ab, b.neg()).eql(a));
    // 倍点、分配律：a + a = 2a
    try expect(C.add(a, a).eql(C.double(a)) and C.double(a).eql(C.mul(be(14, m), g)));
    try expect(C.mul(be(0, m), a).isInfinity());
}

test "ecc: BigBackend point arithmetic obeys the group laws on all six curves (12.4.4.2.1)" {
    inline for (.{ sg.Id.ecc_21, sg.Id.ecc_25, sg.Id.ecc_26, sg.Id.ecc_28, sg.Id.ecc_29, sg.Id.ecc_30 }) |id| {
        try curveLaws(id);
    }
}

test "ecc: BigBackend with 32-bit limbs (the rv32 path) gives the same d*G on 21, 26, 30" {
    inline for (.{ sg.Id.ecc_21, sg.Id.ecc_26, sg.Id.ecc_30 }) |id| {
        const C = sg.CurveOf(id, 32);
