        const pts = switch (id) {
            .ecc_21 => &dg_21,
            .ecc_26 => &dg_26,
            else => &dg_30,
        };
        for (pts) |p| {
            const bytes = C.mul(p.d[0..m].*, C.PointT.base).toBytes();
            try expectEqualSlices(u8, p.x, bytes[0..m]);
            try expectEqualSlices(u8, p.y, bytes[m..]);
        }
    }
}

// ---------------------------------------------------------------------------
// 3) bignum：域运算
// ---------------------------------------------------------------------------

fn fieldLaws(comptime prime: []const u8, comptime limb_bits: u32) !void {
    const F = bignum.Field(prime, limb_bits);
    var raw: [prime.len]u8 = undefined;
    rngFill(&raw);
    raw[0] = 0; // 最高字节清掉，保证小于 p
    const a = F.fromBytes(&raw) orelse return error.TestUnexpectedResult;
    const one = comptime F.fromSmall(1);
    const two = comptime F.fromSmall(2);
    const three = comptime F.fromSmall(3);
    // (a + 1) − 1 = a，2·a = a + a，a·1 = a
    try expect(a.add(one).sub(one).equivalent(a));
    try expect(a.dbl().equivalent(a.add(a)));
    try expect(a.mul(one).equivalent(a));
    try expect(two.add(one).equivalent(three));
    // a·a⁻¹ = 1；a·(1/a·1/a) = 1/a
    const inv = a.invert();
    try expect(a.mul(inv).equivalent(one));
    try expect(a.sq().equivalent(a.mul(a)));
    try expect(a.neg().add(a).isZero());
    try expect(a.isOdd() == (a.toBytes()[prime.len - 1] & 1 == 1));
}

test "bignum: Montgomery field laws on P-224 and P-521 with 64-bit and 32-bit limbs" {
    try fieldLaws(&sg.ecc_26_p, bignum.native_limb_bits);
    try fieldLaws(&sg.ecc_26_p, 32);
    try fieldLaws(&sg.ecc_21_p, bignum.native_limb_bits);
    try fieldLaws(&sg.ecc_21_p, 32);
}

test "bignum: Field.fromBytes rejects values not below p (12.4.7.2.5)" {
    const F = bignum.Field(&sg.ecc_26_p, bignum.native_limb_bits);
    try expect(F.fromBytes(&sg.ecc_26_p) == null);
    var one_more = sg.ecc_26_p;
    one_more[27] += 1;
    try expect(F.fromBytes(&one_more) == null);
    const zero: [28]u8 = @splat(0);
    try expect(F.fromBytes(&zero) != null);
}

fn powAll(comptime id: sg.Id, comptime vecs: []const PowVec) !void {
    const G = sg.Group(id);
    const m = G.m;
    inline for (vecs) |v| {
        const got = G.rawPow(v.base[0..m], &be(v.exp, m));
        try expectEqualSlices(u8, v.want, &got);
    }
}

fn invAll(comptime id: sg.Id, vecs: []const InvVec) !void {
    const G = sg.Group(id);
    const m = G.m;
    // 模逆是 a^(p−2)：底数是模 p 的任意整数，不要求在子群里，所以走不校验的 rawPow
    var p_minus_2 = G.prime.*;
    p_minus_2[m - 1] -= 2;
    for (vecs) |v| {
        const got = G.rawPow(v.base[0..m], &p_minus_2);
        try expectEqualSlices(u8, v.want, &got);
    }
}

test "bignum: FFC modular exponentiation base^exp mod p equals Python pow() (12.4.4.3.1)" {
    try powAll(.ffc_2, &pow_2);
    try powAll(.ffc_5, &pow_5);
    try powAll(.ffc_14, &pow_14);
    try powAll(.ffc_15, &pow_15);
    try powAll(.ffc_16, &pow_16);
    try powAll(.ffc_17, &pow_17);
    try powAll(.ffc_18, &pow_18);
}

test "bignum: FFC inversion a^(p-2) equals Python pow(); the 32-bit limb path matches (12.4.4.3.1)" {
    try invAll(.ffc_2, &inv_2);
    try invAll(.ffc_5, &inv_5);
    try invAll(.ffc_14, &inv_14);
    try invAll(.ffc_15, &inv_15);
    const G = sg.GroupWithLimbs(.ffc_2, 32);
    var p_minus_2: [128]u8 = G.prime.*;
    p_minus_2[127] -= 2;
    for (inv_2) |v| {
        try expectEqualSlices(u8, v.want, &G.rawPow(v.base[0..128], &p_minus_2));
    }
    inline for (pow_2) |v| {
        try expectEqualSlices(u8, v.want, &G.rawPow(v.base[0..128], &be(v.exp, 128)));
    }
}

