// 给 hook 用的「坏」pwd-value：前 `bad` 轮坏，之后放行。`bad` 取一条整链向量里第一个能用的
// counter 加一，这样期望值就是「从 bad + 1 起第一个能用的 counter」，由 firstUsable 独立算出。
const bad_25: u8 = kat_25[0].counter + 1;
const bad_2: u8 = kat_2[0].counter + 1;

fn hookGeP25(seed: [sae.hash_len]u8, counter: u8) [24]u8 {
    return if (counter <= bad_25) @splat(0xff) else sg.Group(.ecc_25).pwdValue(seed);
}

fn hookNoY25(seed: [sae.hash_len]u8, counter: u8) [24]u8 {
    var v = sg.Group(.ecc_25).pwdValue(seed);
    if (counter <= bad_25) {
        // x = 4：oracle 确认 P-192 上 x³ − 3x + b 对 x = 4 不是二次剩余
        @memset(&v, 0);
        v[23] = 4;
    }
    return v;
}

fn hookAllGeP25(seed: [sae.hash_len]u8, counter: u8) [24]u8 {
    _ = seed;
    _ = counter;
    return @splat(0xff);
}

fn hookGeP2(seed: [sae.hash_len]u8, counter: u8) [128]u8 {
    return if (counter <= bad_2) @splat(0xff) else sg.Group(.ffc_2).pwdValue(seed);
}

fn hookOne2(seed: [sae.hash_len]u8, counter: u8) [128]u8 {
    var v = sg.Group(.ffc_2).pwdValue(seed);
    if (counter <= bad_2) {
        @memset(&v, 0);
        v[127] = 1;
    }
    return v;
}

/// 从 `start` 起，用群自己的 tryPwe 找第一个能用的 counter（不经过 hook 那套循环）。
fn firstUsable(comptime G: type, kat: Kat, start: u8, out: *[G.element_len]u8) ?u8 {
    var c: u16 = start;
    while (c <= 255) : (c += 1) {
        const seed = sae.pwdSeedOctet(macOf(kat.mac_a), macOf(kat.mac_b), kat.password, @intCast(c));
        if (G.tryPwe(&G.pwdValue(seed), seed, out)) return @intCast(c);
    }
    return null;
}

fn huntHooked(comptime id: sg.Id, comptime hook: anytype, kat: Kat, out: []u8) !u8 {
    return sg.huntHooked(id, hook, macOf(kat.mac_a), macOf(kat.mac_b), kat.password, out);
}

test "sae groups: hunting-and-pecking skips pwd-value >= p and x with no y, then keeps counting (12.4.4.2.2)" {
    const G = sg.Group(.ecc_25);
    const kat = kat_25[0];
    var want: [G.element_len]u8 = undefined;
    var got: [G.element_len]u8 = undefined;
    // 从 bad_25 + 1 起第一个能用的 counter（不一定就是 bad_25 + 1：每一轮约一半的概率没有 y）
    const want_c = firstUsable(G, kat, bad_25 + 1, &want) orelse return error.TestUnexpectedResult;
    try expect(want_c > kat.counter);
    // 前 bad_25 轮不小于 p：跳过
    try expectEqual(want_c, try huntHooked(.ecc_25, hookGeP25, kat, &got));
    try expectEqualSlices(u8, &want, &got);
    // 前 bad_25 轮 x = 4（没有 y）：跳过
    try expectEqual(want_c, try huntHooked(.ecc_25, hookNoY25, kat, &got));
    try expectEqualSlices(u8, &want, &got);
}

test "sae groups: FFC hunting-and-pecking skips pwd-value >= p and candidate PWE = 1 (12.4.4.3.2)" {
    const G = sg.Group(.ffc_2);
    const kat = kat_2[0];
    var want: [G.element_len]u8 = undefined;
    var got: [G.element_len]u8 = undefined;
    const want_c = firstUsable(G, kat, bad_2 + 1, &want) orelse return error.TestUnexpectedResult;
    try expectEqual(want_c, try huntHooked(.ffc_2, hookGeP2, kat, &got));
    try expectEqualSlices(u8, &want, &got);
    try expectEqual(want_c, try huntHooked(.ffc_2, hookOne2, kat, &got));
    try expectEqualSlices(u8, &want, &got);
}

test "sae groups: hunting-and-pecking gives up after 255 counters with error.NotFound (12.4.4.2.2)" {
    var pwe: [sg.params(.ecc_25).element_len]u8 = undefined;
    try expectError(error.NotFound, sg.huntHooked(.ecc_25, hookAllGeP25, mac_a, mac_b, pw, &pwe));
}

test "sae groups: group 19 via sae_full.derivePwe equals sae_groups.Group(19).hunt (12.4.4.2.2)" {
    const a = try sf.derivePwe(mac_a, mac_b, pw);
    const G = sg.Group(.ecc_19);
    var buf: [G.element_len]u8 = undefined;
    const c = try G.hunt(null, mac_a, mac_b, pw, &buf);
    try expectEqual(a.counter, c);
    try expectEqualSlices(u8, &a.point.toBytes(), &buf);
}

// ---------------------------------------------------------------------------
// 5) 整链向量：PWE → commit → K → KCK/PMK/PMKID → confirm
// ---------------------------------------------------------------------------

fn checkPwe(comptime G: type, kat: Kat) !void {
    var pwe: [G.element_len]u8 = undefined;
    const counter = try G.hunt(null, macOf(kat.mac_a), macOf(kat.mac_b), kat.password, &pwe);
    try expectEqual(kat.counter, counter);
    try expectEqualSlices(u8, kat.pwe, &pwe);
    const seed = sae.pwdSeedOctet(macOf(kat.mac_a), macOf(kat.mac_b), kat.password, counter);
    try expectEqualSlices(u8, kat.pwd_value, &G.pwdValue(seed));
}

/// 一条整链：PWE，两端的 commit-scalar / COMMIT-ELEMENT，两边的 K 与 F(K)，
/// KCK / PMK / PMKID，两条 confirm。
fn checkChain(comptime id: sg.Id, comptime G: type, kat: Kat) !void {
    const m = G.m;
    const n = G.element_len;
    try checkPwe(G, kat);
    var pwe: [n]u8 = undefined;
    _ = try G.hunt(null, macOf(kat.mac_a), macOf(kat.mac_b), kat.password, &pwe);

    var elem_a: [n]u8 = undefined;
    var elem_b: [n]u8 = undefined;
    try G.commitElement(kat.mask_a[0..m], &pwe, &elem_a);
    try G.commitElement(kat.mask_b[0..m], &pwe, &elem_b);
    try expectEqualSlices(u8, kat.element_a, &elem_a);
    try expectEqualSlices(u8, kat.element_b, &elem_b);
    var scalar_a: [m]u8 = undefined;
    var scalar_b: [m]u8 = undefined;
    sg.scalarAdd(id, kat.rand_a[0..m], kat.mask_a[0..m], &scalar_a);
    sg.scalarAdd(id, kat.rand_b[0..m], kat.mask_b[0..m], &scalar_b);
    try expectEqualSlices(u8, kat.scalar_a, &scalar_a);
    try expectEqualSlices(u8, kat.scalar_b, &scalar_b);

    var k_a: [m]u8 = undefined;
    var k_b: [m]u8 = undefined;
    try G.sharedK(kat.rand_a[0..m], &pwe, kat.scalar_b[0..m], kat.element_b[0..n], &k_a);
    try G.sharedK(kat.rand_b[0..m], &pwe, kat.scalar_a[0..m], kat.element_a[0..n], &k_b);
    try expectEqualSlices(u8, kat.k, &k_a);
    try expectEqualSlices(u8, kat.k, &k_b);
    try G.elementValid(kat.element_a[0..n]);
    try G.elementValid(kat.element_b[0..n]);

    var sum: [m]u8 = undefined;
    sg.scalarAdd(id, kat.scalar_a[0..m], kat.scalar_b[0..m], &sum);
    const d = sae.kckPmk(&k_a, &sum);
    try expectEqualSlices(u8, kat.keyseed, &d.keyseed);
    try expectEqualSlices(u8, kat.kck, &d.kck);
    try expectEqualSlices(u8, kat.pmk, &d.pmk);
    try expectEqualSlices(u8, kat.pmkid, sum[0..sae.pmkid_len]);

    try expectEqualSlices(u8, kat.confirm_a, &sae.confirmMac(d.kck, 1, kat.scalar_a[0..m], kat.element_a[0..n], kat.scalar_b[0..m], kat.element_b[0..n]));
    try expectEqualSlices(u8, kat.confirm_b, &sae.confirmMac(d.kck, 1, kat.scalar_b[0..m], kat.element_b[0..n], kat.scalar_a[0..m], kat.element_a[0..n]));
    // 运行时分派的那一套给出同一个结果
    var pwe2: [sg.max_element_len]u8 = undefined;
    _ = try sg.derivePwe(id, macOf(kat.mac_a), macOf(kat.mac_b), kat.password, pwe2[0..n]);
    try expectEqualSlices(u8, &pwe, pwe2[0..n]);
    var k2: [sg.max_prime_len]u8 = undefined;
    try sg.sharedK(id, kat.rand_a[0..m], &pwe, kat.scalar_b[0..m], kat.element_b[0..n], k2[0..m]);
    try expectEqualSlices(u8, &k_a, k2[0..m]);
    var e2: [sg.max_element_len]u8 = undefined;
    try sg.commitElement(id, kat.mask_a[0..m], &pwe, e2[0..n]);
    try expectEqualSlices(u8, &elem_a, e2[0..n]);
}

fn chainAll(comptime id: sg.Id, kats: []const Kat) !void {
    for (kats) |kat| try checkChain(id, sg.Group(id), kat);
}

fn pweAll(comptime id: sg.Id, kats: []const Kat) !void {
    for (kats) |kat| try checkPwe(sg.Group(id), kat);
}

