// ---------------------------------------------------------------------------
// 6) 标量、校验与运算律
// ---------------------------------------------------------------------------

test "sae groups: scalar mod r addition carries, reduction and the range check (12.4.5.2, 12.4.5.4)" {
    inline for (.{ sg.Id.ecc_19, sg.Id.ecc_21, sg.Id.ffc_2 }) |id| {
        const G = sg.Group(id);
        const m = G.m;
        const r = G.order.*;
        // r 是奇数：r − 1 只动最后一个字节
        var r_minus_1 = r;
        r_minus_1[m - 1] -= 1;
        var seven: [m]u8 = @splat(0);
        seven[m - 1] = 7;
        var sum: [m]u8 = undefined;
        const zero: [m]u8 = @splat(0);
        sg.scalarAdd(id, &r_minus_1, &seven, &sum);
        try expect(std.mem.allEqual(u8, sum[0 .. m - 1], 0) and sum[m - 1] == 6);
        sg.scalarAdd(id, &r_minus_1, &r_minus_1, &sum);
        var r_minus_2 = r;
        r_minus_2[m - 1] -= 2;
        try expectEqualSlices(u8, &r_minus_2, &sum);
        var one: [m]u8 = @splat(0);
        one[m - 1] = 1;
        sg.scalarAdd(id, &r_minus_1, &one, &sum);
        try expectEqualSlices(u8, &zero, &sum);
        // 归约：r + 5 → 5；r 的最高字节非 0，所以最多减 255 次
        var raw: [m]u8 = undefined;
        rngFill(&raw);
        var red: [m]u8 = undefined;
        sg.scalarFromRandom(id, &raw, &red);
        try expect(sg.scalarValid(id, &red));
        // 范围：0 拒绝、r 拒绝、r−1 接受
        try expect(!sg.scalarValid(id, &zero));
        try expect(!sg.scalarValid(id, &r));
        try expect(sg.scalarValid(id, &r_minus_1));
    }
}

fn eccNegatives(comptime id: sg.Id, kats: []const Kat) !void {
    const G = sg.Group(id);
    const m = G.m;
    const n = G.element_len;
    const kat = kats[0];
    var pwe: [n]u8 = undefined;
    _ = try G.hunt(null, macOf(kat.mac_a), macOf(kat.mac_b), kat.password, &pwe);
    var k: [m]u8 = undefined;
    const zero: [m]u8 = @splat(0);
    const r = G.order.*;
    var r_plus_1 = r;
    r_plus_1[m - 1] += 1;
    // scalar：0、r、r+1 → Scalar
    try expectError(error.Scalar, G.sharedK(kat.rand_a[0..m], &pwe, &zero, kat.element_b[0..n], &k));
    try expectError(error.Scalar, G.sharedK(kat.rand_a[0..m], &pwe, &r, kat.element_b[0..n], &k));
    try expectError(error.Scalar, G.sharedK(kat.rand_a[0..m], &pwe, &r_plus_1, kat.element_b[0..n], &k));
    // 元素：x 不小于 p、x = 0、y = 0、不在曲线上 → Element
    var bad: [n]u8 = undefined;
    @memcpy(&bad, kat.element_b[0..n]);
    @memcpy(bad[0..m], G.prime);
    try expectError(error.Element, G.sharedK(kat.rand_a[0..m], &pwe, kat.scalar_b[0..m], &bad, &k));
    @memcpy(&bad, kat.element_b[0..n]);
    @memset(bad[0..m], 0);
    try expectError(error.Element, G.sharedK(kat.rand_a[0..m], &pwe, kat.scalar_b[0..m], &bad, &k));
    @memcpy(&bad, kat.element_b[0..n]);
    @memset(bad[m..n], 0);
    try expectError(error.Element, G.sharedK(kat.rand_a[0..m], &pwe, kat.scalar_b[0..m], &bad, &k));
    @memcpy(&bad, kat.element_b[0..n]);
    bad[n - 1] ^= 1;
    try expectError(error.Element, G.sharedK(kat.rand_a[0..m], &pwe, kat.scalar_b[0..m], &bad, &k));
    try expectError(error.Element, G.elementValid(&bad));
    // K 是无穷远点：对端的元素取成 inverse(pcs·PWE) → Identity
    var ident: [n]u8 = undefined;
    try G.scalarOp(kat.scalar_b[0..m], &pwe, &ident);
    var inv: [n]u8 = undefined;
    try G.inverseOp(&ident, &inv);
    try expectError(error.Identity, G.sharedK(kat.rand_a[0..m], &pwe, kat.scalar_b[0..m], &inv, &k));
}

test "sae groups: ECC commit validation rejects with the right reason on 19 and 25 (12.4.5.4)" {
    try eccNegatives(.ecc_19, &kat_19);
    try eccNegatives(.ecc_25, &kat_25);
}

fn ffcNegatives(comptime id: sg.Id, kats: []const Kat, nonsub: []const u8) !void {
    const G = sg.Group(id);
    const m = G.m;
    const kat = kats[0];
    var pwe: [m]u8 = undefined;
    _ = try G.hunt(null, macOf(kat.mac_a), macOf(kat.mac_b), kat.password, &pwe);
    var k: [m]u8 = undefined;
    const rand = kat.rand_a[0..m];
    const pcs = kat.scalar_b[0..m];
    // scalar = 0 → Scalar
    const zero: [m]u8 = @splat(0);
    try expectError(error.Scalar, G.sharedK(rand, &pwe, &zero, kat.element_b[0..m], &k));
    // 元素 1、p−1、p、0、子群外 → Element
    var bad: [m]u8 = @splat(0);
    bad[m - 1] = 1;
    try expectError(error.Element, G.sharedK(rand, &pwe, pcs, &bad, &k));
    bad = G.prime.*;
    bad[m - 1] -= 1;
    try expectError(error.Element, G.sharedK(rand, &pwe, pcs, &bad, &k));
    try expectError(error.Element, G.sharedK(rand, &pwe, pcs, G.prime, &k));
    try expectError(error.Element, G.sharedK(rand, &pwe, pcs, &zero, &k));
    try expectError(error.Element, G.sharedK(rand, &pwe, pcs, nonsub[0..m], &k));
    // 单位元：对端的元素是 inverse(pcs·PWE) → K = 1 → Identity
    var ident: [m]u8 = undefined;
    try G.scalarOp(pcs, &pwe, &ident);
    var inv: [m]u8 = undefined;
    try G.inverseOp(&ident, &inv);
    try expectError(error.Identity, G.sharedK(rand, &pwe, pcs, &inv, &k));
    try expectError(error.Identity, G.elemOp(&ident, &inv, &bad));
}

test "sae groups: FFC commit validation rejects 1, p-1, p, 0 and non-subgroup elements with Element (12.4.5.4)" {
    try ffcNegatives(.ffc_2, &kat_2, nonsub_2);
    try ffcNegatives(.ffc_14, &kat_14, nonsub_14);
}

fn axioms(comptime id: sg.Id, kats: []const Kat) !void {
    const G = sg.Group(id);
    const m = G.m;
    const n = G.element_len;
    const kat = kats[0];
    var pwe: [n]u8 = undefined;
    _ = try G.hunt(null, macOf(kat.mac_a), macOf(kat.mac_b), kat.password, &pwe);
    // 标量分配律：(a + b)·PWE = a·PWE ⊕ b·PWE
    var sum: [m]u8 = undefined;
    sg.scalarAdd(id, kat.rand_a[0..m], kat.mask_a[0..m], &sum);
    var lhs: [n]u8 = undefined;
    var ra: [n]u8 = undefined;
    var ma: [n]u8 = undefined;
    var rhs: [n]u8 = undefined;
    var tmp: [n]u8 = undefined;
    try G.scalarOp(&sum, &pwe, &lhs);
    try G.scalarOp(kat.rand_a[0..m], &pwe, &ra);
    try G.scalarOp(kat.mask_a[0..m], &pwe, &ma);
    try G.elemOp(&ra, &ma, &rhs);
    try expectEqualSlices(u8, &lhs, &rhs);
    // elem-op 交换律；scalar-op(1, x) = x；scalar-op(r, x) = 单位元 → Identity
    try G.elemOp(&ma, &ra, &tmp);
    try expectEqualSlices(u8, &rhs, &tmp);
    var one: [m]u8 = @splat(0);
    one[m - 1] = 1;
    try G.scalarOp(&one, &ra, &tmp);
    try expectEqualSlices(u8, &ra, &tmp);
    try expectError(error.Identity, G.scalarOp(G.order, &ra, &tmp));
    // x ⊕ inverse(x) = 单位元
    var inv: [n]u8 = undefined;
    try G.inverseOp(&ra, &inv);
    try expectError(error.Identity, G.elemOp(&ra, &inv, &tmp));
    // inverse(x) 也是 x^(r−1)：scalar-op(r−1, x) 与 inverseOp 相同
    var r_minus_1 = G.order.*;
    r_minus_1[m - 1] -= 1;
    try G.scalarOp(&r_minus_1, &ra, &tmp);
    try expectEqualSlices(u8, &inv, &tmp);
}

test "sae groups: elem-op, scalar-op, inverse-op obey the group laws on 25, 28 and 2 (12.4.4)" {
    try axioms(.ecc_25, &kat_25);
    try axioms(.ecc_28, &kat_28);
    try axioms(.ffc_2, &kat_2);
}

// ---------------------------------------------------------------------------
// 7) 多群的状态机（sae_full.Groups）
// ---------------------------------------------------------------------------

fn NodeOf(comptime cfg: type) type {
    return struct {
        const Self = @This();
        const capacity = 8;
        const Frame = struct { peer: [6]u8, len: u16, body: [cfg.body_max_len]u8 };

        mac: [6]u8 = @splat(0),
        box: [capacity]Frame = undefined,
        len: usize = 0,
        dropped: usize = 0,
        parent: cfg.Parent(2) = undefined,

        fn onFrame(ctx: *anyopaque, peer: [6]u8, body: []const u8) void {
            const self: *Self = @ptrCast(@alignCast(ctx));
            if (self.len == capacity or body.len > cfg.body_max_len) {
                self.dropped += 1;
                return;
            }
            self.box[self.len] = .{ .peer = peer, .len = @intCast(body.len), .body = undefined };
            @memcpy(self.box[self.len].body[0..body.len], body);
            self.len += 1;
        }

        fn init(self: *Self, mac: [6]u8, password: []const u8, password_id: ?[]const u8, threshold: u16) void {
            self.* = .{};
            self.mac = mac;
            self.parent = cfg.Parent(2).init(.{
                .own_mac = mac,
                .password = password,
                .password_id = password_id,
                .random = rngFill,
                // 判据按 1000 ms 推时间
                .timing = .{ .retrans_period_ms = 1_000 },
                .emit = .{ .ctx = self, .frame = onFrame },
            }, .{ .anti_clogging_threshold = threshold });
        }

        fn at(self: *const Self, i: usize) []const u8 {
            return self.box[i].body[0..self.box[i].len];
        }

        fn groupOf(self: *const Self, i: usize) u16 {
            return std.mem.readInt(u16, self.at(i)[6..8], .little);
        }

        fn statusOf(self: *const Self, i: usize) u16 {
            return std.mem.readInt(u16, self.at(i)[4..6], .little);
        }
    };
}

const Mixed = sf.Groups(&.{ .ecc_20, .ecc_19, .ecc_25 });
const OrderBA = sf.Groups(&.{ .ecc_19, .ecc_20 });
const Only19 = sf.Groups(&.{.ecc_19});

var m_a: NodeOf(Mixed) = .{};
var m_b: NodeOf(Mixed) = .{};
var ba_a: NodeOf(OrderBA) = .{};
var ba_b: NodeOf(OrderBA) = .{};
var o19_a: NodeOf(Only19) = .{};
var o19_b: NodeOf(Only19) = .{};

fn bothAccepted(a: anytype, b: anytype) !void {
    const ia = a.parent.accepted(b.mac) orelse return error.TestUnexpectedResult;
    const ib = b.parent.accepted(a.mac) orelse return error.TestUnexpectedResult;
    try expectEqual(ia.group, ib.group);
    try expectEqualSlices(u8, &ia.pmk, &ib.pmk);
    try expectEqualSlices(u8, &ia.pmkid, &ib.pmkid);
    try expectEqual(@as(usize, 1), a.parent.instanceCount());
    try expectEqual(@as(u16, 0), a.parent.openCount());
}

/// a 发起、b 响应：Commit、Commit、Confirm、Confirm 四帧走完。
fn acceptBoth(a: anytype, b: anytype, now_ms: u64) !void {
    _ = a.parent.initiate(b.mac, now_ms);
    b.parent.receive(a.mac, a.at(0), now_ms);
    a.parent.receive(b.mac, b.at(0), now_ms);
    a.parent.receive(b.mac, b.at(1), now_ms);
    b.parent.receive(a.mac, a.at(1), now_ms);
    try bothAccepted(a, b);
}

fn commitLen(comptime id: sg.Id) usize {
    const p = sg.params(id);
    return sf.header_len + 2 + @as(usize, p.prime_len) + p.element_len;
}

fn inst(node: anytype, i: usize) @TypeOf(&node.parent.entries[0].inst) {
    _ = i;
    return &node.parent.entries[0].inst;
}

/// 状态 76 / 77，或只带群字段的 Commit 帧体。
fn statusFrame(comptime cfg: type, out: []u8, status: u16, g: u16) []const u8 {
    return out[0..cfg.encodeStatusCommit(out, status, g, &.{})];
}

test "sae fsm: a multi-group configuration authenticates on the most preferred group (12.4.5.2, 12.4.8.6.3)" {
    m_a.init(mac_a, pw, null, 5);
    m_b.init(mac_b, pw, null, 5);
    try acceptBoth(&m_a, &m_b, 0);
    try expectEqual(@as(u16, 20), m_a.groupOf(0));
    try expectEqual(@as(u16, 20), m_b.groupOf(0));
    try expectEqual(sg.Id.ecc_20, inst(&m_a, 0).group);
    try expectEqual(commitLen(.ecc_20), m_a.at(0).len);
    try expectEqual(commitLen(.ecc_20), m_b.at(0).len);
}

test "sae fsm: the responder uses the initiator's group even when it prefers another (12.4.5.2)" {
    // b 最优先 19，a 最优先 20：b 跟着 a 用 20
    m_a.init(mac_a, pw, null, 5);
    ba_b.init(mac_b, pw, null, 5);
    try acceptBoth(&m_a, &ba_b, 0);
    try expectEqual(sg.Id.ecc_20, inst(&ba_b, 0).group);
    // 反过来：a 接受 b 的 19
    m_a.init(mac_a, pw, null, 5);
    ba_b.init(mac_b, pw, null, 5);
    try acceptBoth(&ba_b, &m_a, 0);
    try expectEqual(sg.Id.ecc_19, inst(&m_a, 0).group);
    try expectEqual(@as(u16, 19), m_a.groupOf(0));
}

test "sae fsm: Rej(77) for the group we offered switches to the next configured group and authenticates there (12.4.8.6.4)" {
    var buf: [Mixed.body_max_len + 8]u8 = undefined;
    m_a.init(mac_a, pw, null, 5);
    o19_b.init(mac_b, pw, null, 5);
    _ = m_a.parent.initiate(mac_b, 0);
    try expectEqual(@as(u16, 20), m_a.groupOf(0));
    const rej = statusFrame(Mixed, &buf, sf.status_group_not_supported, 20);
    m_a.parent.receive(mac_b, rej, 1);
    // 配置里还有没提供过的群（moregroups）：换成 19，重新生成，Sync 清零，留在 Committed
    try expectEqual(@as(usize, 2), m_a.len);
    try expectEqual(@as(u16, 19), m_a.groupOf(1));
    try expectEqual(commitLen(.ecc_19), m_a.at(1).len);
    try expectEqual(sg.Id.ecc_19, inst(&m_a, 0).group);
    try expectEqual(@as(u16, 0), inst(&m_a, 0).sync);
    try expectEqual(sf.State.committed, inst(&m_a, 0).state);
    // 之后双方在 19 上走完
    o19_b.parent.receive(mac_a, m_a.at(1), 2);
    m_a.parent.receive(mac_b, o19_b.at(0), 3);
    m_a.parent.receive(mac_b, o19_b.at(1), 4);
    o19_b.parent.receive(mac_a, m_a.at(2), 5);
    try bothAccepted(&m_a, &o19_b);
    try expectEqual(sg.Id.ecc_19, m_a.parent.accepted(mac_b).?.group);
}

