    try expectEqual(sf.status_group_not_supported, o19_a.statusOf(1));
    try expectEqual(@as(u16, 25), o19_a.groupOf(1));
    // 77 的 Commit 只有头部与群字段（`buf` 里还放着 `bad`，不能拿它当输出缓冲）
    try expectEqual(sf.header_len + 2, o19_a.at(1).len);
    try expectEqual(sf.State.committed, inst(&o19_a, 0).state);
    try expectEqual(@as(u16, 1), inst(&o19_a, 0).sync);
    // dot11RSNASAESync = 5：Sync 到 6 还回 77，第 7 次 Sync > 5 → Del
    for (2..8) |t| o19_a.parent.receive(mac_b, bad, t);
    try expectEqual(@as(usize, 0), o19_a.parent.instanceCount());
    try expectEqual(@as(usize, 7), o19_a.len);
    try expectEqual(sf.Signal.del, (o19_a.parent.popEvent() orelse return error.TestUnexpectedResult).signal);
}

/// 两端同时发起、最优先的群不同：数值较小的一端换成对端的群，数值较大的一端只重发。
fn diffGrp(low: anytype, high: anytype, want: sg.Id) !void {
    _ = low.parent.initiate(high.mac, 0);
    _ = high.parent.initiate(low.mac, 0);
    // low 的 Commit 到了 high：high 的 MAC 数值大，丢弃并重发自己的 Commit
    high.parent.receive(low.mac, low.at(0), 1);
    try expectEqual(@as(usize, 2), high.len);
    try expectEqual(high.groupOf(0), high.groupOf(1));
    // high 的 Commit 到了 low：low 换成对端的群，发新 Commit 与 Confirm，进 Confirmed
    low.parent.receive(high.mac, high.at(0), 2);
    try expectEqual(@as(usize, 3), low.len);
    try expectEqual(@backingInt(want), low.groupOf(1));
    try expectEqual(want, inst(low, 0).group);
    try expectEqual(sf.State.confirmed, inst(low, 0).state);
    try expectEqual(@as(u16, 0), inst(low, 0).sync);
    try expectEqual(@as(u16, 1), inst(low, 0).sc);
    // low 的新 Commit 到了 high：同一个群，处理并发 Confirm
    high.parent.receive(low.mac, low.at(1), 3);
    try expectEqual(@as(usize, 3), high.len);
    try expectEqual(sf.State.confirmed, inst(high, 0).state);
    // 互换 Confirm
    low.parent.receive(high.mac, high.at(2), 4);
    high.parent.receive(low.mac, low.at(2), 5);
    try bothAccepted(low, high);
}

