    // 反过来：a 最优先 19，b 最优先 20：都落在 20
    ba_a.init(mac_a, pw, null, 5);
    m_b.init(mac_b, pw, null, 5);
    try diffGrp(&ba_a, &m_b, .ecc_20);
}

