test "password identifier (hostap): element encoder and recogniser follow sae.c:1659-1667 and 1746-1753" {
    var buf: [sf.password_id_elem_max_len]u8 = undefined;
    const e = sf.passwordIdElement(&buf, "staff") orelse return error.TestUnexpectedResult;
    try expectEqualSlices(u8, &[_]u8{ 0xff, 0x06, 0x21, 's', 't', 'a', 'f', 'f' }, e);
    try expectEqualSlices(u8, "staff", sf.passwordIdOf(e) orelse return error.TestUnexpectedResult);
    // 254 个八位组放得下（Length = 255），255 个放不下
    const max: [sf.password_id_max_len]u8 = @splat('y');
    const big = sf.passwordIdElement(&buf, &max) orelse return error.TestUnexpectedResult;
    try expectEqual(sf.password_id_elem_max_len, big.len);
    try expectEqual(@as(u8, 255), big[1]);
    try expectEqualSlices(u8, &max, sf.passwordIdOf(big) orelse return error.TestUnexpectedResult);
    const too_long: [sf.password_id_max_len + 1]u8 = @splat('y');
    try expect(sf.passwordIdElement(&buf, &too_long) == null);
    // 空标识：Length = 1，只有扩展 ID
    const empty = sf.passwordIdElement(&buf, "") orelse return error.TestUnexpectedResult;
    try expectEqualSlices(u8, &[_]u8{ 0xff, 0x01, 0x21 }, empty);
    try expectEqual(@as(usize, 0), (sf.passwordIdOf(empty) orelse return error.TestUnexpectedResult).len);
    // 判别：太短、Element ID 不对、Length 为 0、Length 超出、Length 没占满、扩展 ID 不对
    try expect(sf.passwordIdOf(&.{}) == null);
    try expect(sf.passwordIdOf(&.{ 0xff, 0x01 }) == null);
    try expect(sf.passwordIdOf(&.{ 0xfe, 0x06, 0x21, 'a', 'b', 'c', 'd', 'e' }) == null);
    try expect(sf.passwordIdOf(&.{ 0xff, 0x00, 0x21 }) == null);
    try expect(sf.passwordIdOf(&.{ 0xff, 0x06, 0x21, 'a', 'b' }) == null);
    try expect(sf.passwordIdOf(&.{ 0xff, 0x04, 0x21, 'a', 'b', 'c', 'd' }) == null);
    try expect(sf.passwordIdOf(&.{ 0xff, 0x06, 0x22, 'a', 'b', 'c', 'd', 'e' }) == null);
    // 两个元素连在一起不算「恰好一个」
    var two: [16]u8 = undefined;
    @memcpy(two[0..8], e);
    @memcpy(two[8..16], e);
    try expect(sf.passwordIdOf(&two) == null);
    // 一致性判定
    try expect(sf.passwordIdMatches("staff", "staff"));
    try expect(!sf.passwordIdMatches("staff", "staf"));
    try expect(!sf.passwordIdMatches("staff", null));
    try expect(!sf.passwordIdMatches(null, "staff"));
    try expect(sf.passwordIdMatches(null, null));
    try expect(sf.passwordIdMatches("", ""));
}

test "password identifier (hostap): coexists with a token in a Commit; the token request carries none" {
    var buf: [Only19.body_max_len + 8]u8 = undefined;
    const token = [_]u8{ 0xde, 0xad, 0xbe, 0xef, 0x42 };
    const scalar: [32]u8 = @splat(0x11);
    const element: [64]u8 = @splat(0x22);
    const len = Only19.encodeOffer(&buf, .ecc_19, &token, &scalar, &element, "staff") orelse return error.TestUnexpectedResult;
    const c = (try Only19.decode(buf[0..len])).commit;
    try expectEqualSlices(u8, &token, c.token);
    try expectEqualSlices(u8, "staff", c.password_id orelse return error.TestUnexpectedResult);
    try expectEqualSlices(u8, &scalar, &(c.scalar orelse return error.TestUnexpectedResult));
    try expectEqualSlices(u8, &element, &(c.element orelse return error.TestUnexpectedResult));
    // 只带标识、不带 token；标识 30 个八位组（hostap 非 H2E 会把它误当 token：sae.c:1806–1818）
    const long_id: [30]u8 = @splat('i');
    const len2 = Only19.encodeOffer(&buf, .ecc_19, &.{}, &scalar, &element, &long_id) orelse return error.TestUnexpectedResult;
    const c2 = (try Only19.decode(buf[0..len2])).commit;
    try expectEqual(@as(usize, 0), c2.token.len);
    try expectEqualSlices(u8, &long_id, c2.password_id orelse return error.TestUnexpectedResult);
    // Anti-Clogging Token 请求（状态 76）：群字段 || token，不带标识（comeback_token.c:100–124）
    o19_a.init(mac_a, pw, "staff", 0);
    o19_b.init(mac_b, pw, "staff", 0);
    _ = o19_a.parent.initiate(mac_b, 0);
    o19_b.parent.receive(mac_a, o19_a.at(0), 1);
    const req = o19_b.at(0);
    try expectEqual(sf.status_token_required, o19_b.statusOf(0));
    try expectEqual(sf.header_len + 2 + 32, req.len);
    const r = (try Only19.decode(req)).commit;
    try expectEqual(@as(usize, 32), r.token.len);
    try expect(r.password_id == null);
    try expectEqual(@as(u16, 19), r.group orelse return error.TestUnexpectedResult);
    // 带 token 与标识重发：双方 Accepted
    o19_a.parent.receive(mac_b, req, 2);
    try expectEqual(Only19.commit_body_len + 32 + 8, o19_a.at(1).len);
    const again = (try Only19.decode(o19_a.at(1))).commit;
    try expectEqualSlices(u8, r.token, again.token);
    try expectEqualSlices(u8, "staff", again.password_id orelse return error.TestUnexpectedResult);
    o19_b.parent.receive(mac_a, o19_a.at(1), 3);
    try expectEqual(@as(usize, 3), o19_b.len);
    o19_a.parent.receive(mac_b, o19_b.at(1), 4);
    o19_a.parent.receive(mac_b, o19_b.at(2), 5);
    o19_b.parent.receive(mac_a, o19_a.at(2), 6);
    try bothAccepted(&o19_a, &o19_b);
}

