// ---------------------------------------------------------------------------
// 8b) Rejected Groups 元素（802.11-2016 无此条款；依据 hostap）
// ---------------------------------------------------------------------------

/// 状态 126 的 group 19 Commit 帧体：群 || scalar || element || Rejected Groups 元素（列表 `list`）。
fn h2eCommit(out: []u8, list: []const u16) []const u8 {
    var scalar: [Only19.scalar_len]u8 = @splat(0x11);
    var element: [Only19.element_len]u8 = @splat(0x22);
    const n = Only19.encodeOffer(out, .ecc_19, &.{}, &scalar, &element, null) orelse unreachable;
    const tail = sf.rejectedGroupsElement(out[n..], list) orelse unreachable;
    std.mem.writeInt(u16, out[4..6], sf.status_sae_hash_to_element, .little);
    return out[0 .. n + tail.len];
}

test "rejected groups (hostap): the element is 255 | 1+2n | 92 | LE16 list in the given order (sae.c:1672-1676)" {
    var buf: [sf.rejected_groups_elem_max_len]u8 = undefined;
    // 手排：3 个群 19、5、25，Length = 1 + 6 = 7；19 = 0x0013、5 = 0x0005、25 = 0x0019，都是小端
    const want = [_]u8{ 0xff, 0x07, 0x5c, 0x13, 0x00, 0x05, 0x00, 0x19, 0x00 };
    const got = sf.rejectedGroupsElement(&buf, &.{ 19, 5, 25 }) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualSlices(u8, &want, got);
    // 空列表：只有头，Length = 1（载荷 0 个八位组）
    const empty = sf.rejectedGroupsElement(&buf, &.{}) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualSlices(u8, &.{ 0xff, 0x01, 0x5c }, empty);
    // 128 个群放不进 1 个八位组的 Length（1 + 256 > 255）；输出缓冲太短也不行
    const many: [128]u16 = @splat(19);
    try std.testing.expect(sf.rejectedGroupsElement(&buf, &many) == null);
    try std.testing.expect(sf.rejectedGroupsElement(buf[0..8], &.{ 19, 5, 25 }) == null);
}

test "rejected groups (hostap): recogniser needs 3 octets, EID 255, Length within the frame, ext ID 92 (sae.c:1756-1763)" {
