    try std.testing.expect(!sf.isRejectedGroupsElement(e[0..6])); // Length 5，帧里只剩 4 个八位组
    // 别的扩展元素：扩展 ID 33（Password Identifier）不是它
    const p = [_]u8{ 0xff, 0x04, 0x21, 0x61, 0x62, 0x63 };
