test "rejected groups (hostap): parser yields the list; Length 0 or past the end is RejectedGroupsLength, odd payload is RejectedGroupsOdd (sae.c:2056-2068)" {
    // Length 5 = 扩展 ID + 4 个八位组：两个群 19、25
    const f = [_]u8{ 0xff, 0x05, 0x5c, 0x13, 0x00, 0x19, 0x00, 0xaa };
    const r = try sf.rejectedGroupsOf(&f);
    try std.testing.expectEqualSlices(u8, &.{ 0x13, 0x00, 0x19, 0x00 }, r.list);
    // 解析位置停在元素之后（2077）
    try std.testing.expectEqualSlices(u8, &.{0xaa}, r.rest);
    // 空列表合法：Length 恰好只有扩展 ID
    const empty = try sf.rejectedGroupsOf(&.{ 0xff, 0x01, 0x5c });
    try std.testing.expectEqual(@as(usize, 0), empty.list.len);
    // Length 0：识别器看第三个八位组是 92 会认下，解析器在 len < 1 处拒绝（2059–2060）
    try std.testing.expectError(error.RejectedGroupsLength, sf.rejectedGroupsOf(&.{ 0xff, 0x00, 0x5c, 0x00, 0x00 }));
    // Length 超出帧尾（2060 的前半句）
    try std.testing.expectError(error.RejectedGroupsLength, sf.rejectedGroupsOf(&.{ 0xff, 0x07, 0x5c, 0x13, 0x00 }));
    // 载荷 3 个八位组：奇数（2064–2068）
    try std.testing.expectError(error.RejectedGroupsOdd, sf.rejectedGroupsOf(&.{ 0xff, 0x04, 0x5c, 0x13, 0x00, 0x19 }));
}

test "rejected groups (hostap): the list is rejected only when it names a group this end has enabled (ap/ieee802_11.c:478-490)" {
    const enabled = [_]u16{ 19, 25 };
    // 两个群 2、5：都不是本端启用的
    const clean = (try sf.rejectedGroupsOffending(&.{ 0x02, 0x00, 0x05, 0x00 }, &enabled)) orelse null;
    try std.testing.expect(clean == null);
    // 25 在列表里：返回那个群
    const hit = (try sf.rejectedGroupsOffending(&.{ 0x02, 0x00, 0x19, 0x00 }, &enabled)) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u16, 25), hit);
    // 空列表通过
    try std.testing.expect((try sf.rejectedGroupsOffending(&.{}, &enabled)) == null);
    // 奇数个八位组不过（471–476）
    try std.testing.expectError(error.RejectedGroupsOdd, sf.rejectedGroupsOffending(&.{ 0x13, 0x00, 0x19 }, &enabled));
}

test "rejected groups (hostap): decode reads the element only from a Commit with status 126, after the password identifier (sae.c:2139-2152)" {
    const C = sf.Groups(&.{ .ecc_19, .ecc_25 });
    var buf: [C.commit_body_len + sf.password_id_elem_max_len + sf.rejected_groups_elem_max_len]u8 = undefined;
    var scalar: [C.scalar_len]u8 = @splat(0x11);
    var element: [C.element_len]u8 = @splat(0x22);
    const n = C.encodeOffer(&buf, .ecc_19, &.{}, &scalar, &element, "lab") orelse return error.TestUnexpectedResult;
    const tail = sf.rejectedGroupsElement(buf[n..], &.{ 2, 19 }) orelse return error.TestUnexpectedResult;
    const full = buf[0 .. n + tail.len];
    // 状态改成 126：scalar、element、Password Identifier、Rejected Groups 依次解出
    std.mem.writeInt(u16, full[4..6], sf.status_sae_hash_to_element, .little);
    const h = (C.decode(full) catch return error.TestUnexpectedResult).commit;
    try std.testing.expectEqual(@as(?u16, 19), h.group);
    try std.testing.expectEqualStrings("lab", h.password_id.?);
    try std.testing.expectEqualSlices(u8, &.{ 0x02, 0x00, 0x13, 0x00 }, h.rejected_groups.?);
    // H2E 的帧里没有裸的 token 字段
    try std.testing.expectEqual(@as(usize, 0), h.token.len);
    // 同样的字节、状态是 0：不是 H2E 的 Commit，尾部两个元素都算 token，列表是 null
    std.mem.writeInt(u16, full[4..6], sf.status_success, .little);
    const plain = (C.decode(full) catch return error.TestUnexpectedResult).commit;
    try std.testing.expect(plain.rejected_groups == null);
    const se = sg.params(.ecc_19);
    try std.testing.expectEqual(@as(usize, full.len - sf.header_len - 2 - se.prime_len - se.element_len), plain.token.len);
    try std.testing.expect(plain.password_id == null);
    // 状态 126 但对端没带这个元素：列表是 null
    std.mem.writeInt(u16, full[4..6], sf.status_sae_hash_to_element, .little);
    const bare = (C.decode(full[0..n]) catch return error.TestUnexpectedResult).commit;
    try std.testing.expect(bare.rejected_groups == null);
    try std.testing.expectEqualStrings("lab", bare.password_id.?);
}

test "rejected groups (hostap): a malformed element in a status-126 Commit fails decode with its own error (sae.c:2059-2068)" {
    const C = sf.Groups(&.{.ecc_19});
    var buf: [C.commit_body_len + sf.rejected_groups_elem_max_len]u8 = undefined;
    var scalar: [C.scalar_len]u8 = @splat(0x11);
    var element: [C.element_len]u8 = @splat(0x22);
    const n = C.encodeOffer(&buf, .ecc_19, &.{}, &scalar, &element, null) orelse return error.TestUnexpectedResult;
    std.mem.writeInt(u16, buf[4..6], sf.status_sae_hash_to_element, .little);
    // 奇数个八位组的载荷
    @memcpy(buf[n..][0..6], &[_]u8{ 0xff, 0x04, 0x5c, 0x13, 0x00, 0x19 });
    try std.testing.expectError(error.RejectedGroupsOdd, C.decode(buf[0 .. n + 6]));
    // Length 0：识别器认下，解析器报错（2059–2060 的 len < 1）
    @memcpy(buf[n..][0..5], &[_]u8{ 0xff, 0x00, 0x5c, 0x00, 0x00 });
    try std.testing.expectError(error.RejectedGroupsLength, C.decode(buf[0 .. n + 5]));
    // Length 0x07 超出帧尾：识别器不认，帧照常解出，列表是 null（1756–1763、2050–2054）
    @memcpy(buf[n..][0..5], &[_]u8{ 0xff, 0x07, 0x5c, 0x13, 0x00 });
    const loose = (C.decode(buf[0 .. n + 5]) catch return error.TestUnexpectedResult).commit;
    try std.testing.expect(loose.rejected_groups == null);
}

test "sae fsm: a Commit whose Rejected Groups list names an enabled group is answered with status 1 (ap/ieee802_11.c:589-592)" {
    o19_b.init(mac_b, pw, null, 5);
    var buf: [Only19.commit_body_len + sf.rejected_groups_elem_max_len]u8 = undefined;
    // 列表里有本端启用的 19
    const f = h2eCommit(&buf, &.{ 2, 19 });
    o19_b.parent.receive(mac_a, f, 0);
    // 回的是只有帧头的 Commit：alg 3、事务序号 1、状态 1（回的状态不是 77，不带群字段：676–692）
    try std.testing.expectEqual(@as(usize, 1), o19_b.len);
    try std.testing.expectEqual(@as(usize, sf.header_len), o19_b.at(0).len);
    try std.testing.expectEqual(@as(u16, sf.seq_commit), std.mem.readInt(u16, o19_b.at(0)[2..4], .little));
    try std.testing.expectEqual(sf.status_unspecified_failure, o19_b.statusOf(0));
    // 状态 126 的 Commit 不是 2016 的 Com 事件：实例照常结束（Nothing + Com 的 Del）
    try std.testing.expectEqual(@as(usize, 0), o19_b.parent.instanceCount());
}

test "sae fsm: a Rejected Groups list with no enabled group gets no status-1 reply (ap/ieee802_11.c:478-490)" {
    o19_b.init(mac_b, pw, null, 5);
    var buf: [Only19.commit_body_len + sf.rejected_groups_elem_max_len]u8 = undefined;
    // 2、5 都不是本端启用的：不回状态 1
    const f = h2eCommit(&buf, &.{ 2, 5 });
    o19_b.parent.receive(mac_a, f, 0);
    try std.testing.expectEqual(@as(usize, 0), o19_b.len);
    try std.testing.expectEqual(@as(usize, 0), o19_b.parent.instanceCount());
}

